import {cases,colours} from './data.js?v=4';
const $=s=>document.querySelector(s);
let lang='en',idx=0,step=0,selected=null,wrong=false,revealed=false,foilOpen=false,sound=false,scene=null,revealTimer=null;
let completed=new Set();
// A new language preference starts in English, including visitors to the old version.
try{lang=localStorage.getItem('chroma-language-v2')||'en';const saved=JSON.parse(localStorage.getItem('chroma-progress-v2')||'[]');if(Array.isArray(saved))completed=new Set(saved.filter(k=>cases.some(c=>'case-'+c.id===k)))}catch{}
if(!['en','zh'].includes(lang))lang='en';
const t=(z,e)=>lang==='zh'?z:e,txt=a=>a[lang==='zh'?0:1];
const names={leaf:['綠葉','Green leaf'],variegated:['斑葉','Variegated leaf'],worm:['麵包蟲','Mealworm'],soda:['鈉石灰','Soda lime'],control:['對照組','Control']};
const rateOptions=[['呼吸作用速率 > 光合作用速率','Respiration rate > photosynthesis rate'],['光合作用速率 > 呼吸作用速率','Photosynthesis rate > respiration rate'],['兩種作用持續進行，速率相等','Both processes continue at equal rates']];
const colourName=k=>({yellow:t('黃色','Yellow'),red:t('紅色','Red'),purple:t('紫色','Purple')})[k];
const netText=k=>k==='yellow'?t('淨釋放 二氧化碳','Net release of carbon dioxide'):k==='purple'?t('淨移除 二氧化碳','Net removal of carbon dioxide'):t('沒有 二氧化碳 淨交換','No net carbon dioxide exchange');
const concText=k=>k==='yellow'?t('二氧化碳 濃度上升','Carbon dioxide concentration increases'):k==='purple'?t('二氧化碳 濃度下降','Carbon dioxide concentration decreases'):t('二氧化碳 濃度大致不變','Carbon dioxide concentration stays approximately unchanged');
const colourText=k=>k==='red'?t('維持紅色','Stays red'):t(`紅色 → ${colourName(k)}`,`Red → ${colourName(k)}`);
function current(){return cases[idx]}
function steps(){return ['soda','control'].includes(current().kind)?['net','concentration','colour']:['rate','net','concentration','colour']}
function reset(){clearTimeout(revealTimer);revealTimer=null;step=0;selected=null;wrong=false;revealed=false;foilOpen=false;scene?.resetLiquid()}
function save(key){completed.add(key);try{localStorage.setItem('chroma-progress-v2',JSON.stringify([...completed]))}catch{}progress()}
function progress(){$('#progress').textContent=`${completed.size} / ${cases.length}`;$('#progress-fill').style.width=`${completed.size/cases.length*100}%`;renderScenarios()}
function beep(ok=true){if(!sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=ok?660:240;g.gain.setValueAtTime(.04,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.18);o.start();o.stop(ctx.currentTime+.2);o.onended=()=>ctx.close()}catch{}}
function renderScenarios(){$('#scenarios').innerHTML=cases.map((c,i)=>`<button class="scenario ${i===idx?'active':''}" data-case="${i}" aria-pressed="${i===idx}"><b>${txt(c.name)}</b>${completed.has('case-'+c.id)?'<span class="check">✓</span>':''}</button>`).join('');document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{idx=Number(b.dataset.case);reset();render()})}
function render(){document.documentElement.lang=lang==='zh'?'zh-Hant':'en';document.title=t('色彩實驗室','Chroma Lab');$('#brand-name').textContent=t('色彩實驗室','Chroma Lab');document.querySelectorAll('[data-zh]').forEach(e=>e.textContent=e.dataset[lang]);$('#lang').textContent=t('切換語言','Switch language');$('#lang').title=t('切換為英文','Switch to Chinese');$('#sound').textContent=t(sound?'♫ 音效開':'♫ 音效關',sound?'♫ Sound on':'♫ Sound off');$('#guide').setAttribute('aria-label',t('說明','Help'));$('#viewport').setAttribute('aria-label',t('拖曳或使用方向鍵旋轉實驗裝置','Drag or use arrow keys to rotate the experiment'));$('.close').setAttribute('aria-label',t('關閉','Close'));$('#rotate-hint').textContent=t('↔ 旋轉','↔ Rotate');renderTask();progress();updateScene()}
function label(s){return({rate:t('作用速率','Rates'),net:t('淨交換','Net exchange'),concentration:t('濃度','Concentration'),colour:t('顏色','Colour')})[s]}
function choices(){const c=current(),s=steps()[step];if(s==='rate')return rateOptions.map((a,i)=>({value:String(i),text:txt(a)}));if(s==='net'&&c.kind==='soda')return[{value:'purple',text:t('鈉石灰吸收 二氧化碳','Soda lime absorbs carbon dioxide')},{value:'yellow',text:t('鈉石灰釋放 二氧化碳','Soda lime releases carbon dioxide')},{value:'red',text:t('鈉石灰不影響 二氧化碳','Soda lime does not affect carbon dioxide')}];return ['yellow','red','purple'].map(k=>({value:k,text:s==='net'?netText(k):s==='concentration'?concText(k):colourText(k)}))}
function correct(){const c=current();return steps()[step]==='rate'?String(c.p===c.r?2:c.r>c.p?0:1):c.colour}
function question(){const c=current();return({rate:t('比較兩種作用的速率。','Compare the two rates.'),net:c.kind==='soda'?t('鈉石灰如何影響 二氧化碳？','How does soda lime affect carbon dioxide?'):t('二氧化碳 的淨交換是甚麼？','What is the net carbon dioxide exchange?'),concentration:t('二氧化碳 濃度如何改變？','How does carbon dioxide concentration change?'),colour:t('指示劑會如何變色？','How will the indicator change colour?')})[steps()[step]]}
function explanation(c){return lang==='en'?c.en:`${c.why[0]}${netText(c.colour)}，${concText(c.colour)}，指示劑${c.colour==='red'?'維持紅色':`由紅色變成${colourName(c.colour)}`}。`}
function renderTask(){const c=current(),list=steps();$('#task').innerHTML=`<div class="chain-trail">${list.map((s,i)=>`<span class="${i<step?'done':i===step?'current':''}">${i<step?'✓ ':''}${label(s)}</span>`).join('')}</div>`+(revealed?`<div class="feedback" role="status"><b>${t('✓ 正確','✓ Correct')}</b><p>${explanation(c)}</p></div><button class="primary" id="next">${t('下一個樣本 →','Next specimen →')}</button><button class="text-button replay" id="replay">${t('↺ 重播動畫','↺ Replay animation')}</button>`:`<h2>${question()}</h2><div class="answers">${choices().map(o=>`<button class="answer ${selected===o.value?'selected':''}" data-answer="${o.value}" aria-pressed="${selected===o.value}">${list[step]==='colour'?`<span class="swatch" style="background:${colours[o.value]}"></span>`:''}<span>${o.text}</span><span class="radio"></span></button>`).join('')}</div>${wrong?`<p class="retry" role="alert">${t('再想一想。','Try again.')}</p>`:''}<button class="primary" id="submit" ${selected===null?'disabled':''}>${list[step]==='colour'?t('確認並播放 →','Check & play →'):t('下一步 →','Next →')}</button>${step>0?`<button class="text-button back" id="back">${t('← 上一步','← Back')}</button>`:''}`);
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{selected=b.dataset.answer;wrong=false;renderTask()});if($('#submit'))$('#submit').onclick=submit;if($('#back'))$('#back').onclick=()=>{step--;selected=null;wrong=false;renderTask()};if($('#next'))$('#next').onclick=()=>{idx=(idx+1)%cases.length;reset();render()};if($('#replay'))$('#replay').onclick=()=>{scene?.resetLiquid();playResult()};
}
function playResult(){clearTimeout(revealTimer);const box=$('#viewport').getBoundingClientRect();if(box.top<0||box.bottom>innerHeight){$('#viewport').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});revealTimer=setTimeout(()=>{updateScene(false);revealTimer=null},450)}else updateScene(false)}
function submit(){if(selected!==correct()){wrong=true;beep(false);renderTask();return}beep();step++;selected=null;wrong=false;if(step===steps().length){revealed=true;save('case-'+current().id);renderTask();playResult();return}renderTask()}
function updateScene(rebuild=true){const c=current(),col=revealed?c.colour:'red';if(scene){scene.update(c,col,rebuild);scene.cutaway(foilOpen)}$('#scene-title').textContent=txt(c.name);$('#label-specimen').textContent=txt(names[c.kind]);$('#label-liquid').textContent=t('碳酸氫鹽指示劑','Hydrogencarbonate indicator');$('#cutaway').hidden=!c.foil;$('#cutaway').textContent=foilOpen?t('還原鋁箔','Close cutaway'):t('透視鋁箔','View inside foil');if($('#fallback span'))$('#fallback span').style.background=`linear-gradient(to top,${colours[col]} 30%,transparent 30%)`}
function showHelp(){$('#guide-content').innerHTML=`<h2>${t('玩法','How to play')}</h2><p>${t('先比較作用速率，再判斷 二氧化碳 的淨交換及濃度，最後選擇顏色。全部答對後，裝置才會顯示結果。','Compare the rates, explain net carbon dioxide exchange and concentration, then choose the colour. The result appears after every step is correct.')}</p><p>${t('鈉石灰和對照組從 二氧化碳 的變化開始。','Soda lime and the control start with carbon dioxide exchange.')}</p><p>${t('各試管均密封，初始與空氣平衡；樣本與液體分隔。斑葉強光情境假設整片葉的光合作用快於呼吸作用。','Tubes are sealed and initially equilibrated with air; specimens are separated from the liquid. The bright-light variegated case assumes whole-leaf photosynthesis exceeds respiration.')}</p><p>${t('透視鋁箔只改變顯示，仍然遮光。','Viewing inside foil changes only the display; the leaf remains shaded.')}</p>`;$('#guide-dialog').showModal()}
$('#lang').onclick=()=>{lang=lang==='en'?'zh':'en';try{localStorage.setItem('chroma-language-v2',lang)}catch{}render()};$('#sound').onclick=()=>{sound=!sound;$('#sound').setAttribute('aria-pressed',sound);$('#sound').textContent=t(sound?'♫ 音效開':'♫ 音效關',sound?'♫ Sound on':'♫ Sound off');beep()};$('#guide').onclick=showHelp;$('.close').onclick=()=>$('#guide-dialog').close();$('#reset-view').onclick=()=>scene?.reset();$('#cutaway').onclick=()=>{foilOpen=!foilOpen;updateScene(false)};
render();try{const {createLab}=await import('./scene.js?v=3');scene=createLab($('#viewport'));updateScene()}catch(e){console.error('3D unavailable',e);$('#fallback').hidden=false;$('#fallback').innerHTML=t('此裝置未能啟動立體模型，仍可作答。','The 3D model could not start on this device. You can still answer the questions.')+'<span></span>';updateScene()}
